// The serial-scanner suite drives scannerImpl.Scan + Identify directly over
// temp fixture libraries that mirror the two ground truths of tasks.md 5.1:
// noisy cours directories with Eng/Rus/SUB sidecars, a deep OST/, a stray
// top-level video, and extensionless smbdelete junk. Fixture files are
// zero-byte unless makeVideoOpt could render real media — every structural
// assertion is ffprobe-independent, so the suite passes without ffmpeg/ffprobe
// (probe soft-fail warnings are filtered by content where it matters).

// writeTree creates every parent directory and empty file for the given
// root-relative paths (slash-separated).
func writeTree(t *testing.T, root string, paths ...string) {
	t.Helper()
	for _, p := range paths {
		abs := filepath.Join(root, filepath.FromSlash(p))
		if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(abs, nil, 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

// makeVideoOpt renders a tiny probeable video at path via ffmpeg's lavfi
// testsrc. Unlike base-scanner's makeMedia it does NOT skip: it reports whether
// real media exists, so tests can assert probe content when available and fall
// back to emission-only assertions when not.
func makeVideoOpt(t *testing.T, path string) bool {
	t.Helper()
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		return false
	}
	_ = exec.Command("ffmpeg",
		"-f", "lavfi",
		"-i", "testsrc=duration=0.3:size=16x16:rate=10",
		"-loglevel", "error",
		"-y",
		filepath.Clean(path),
	).Run()
	info, err := os.Stat(path)
	return err == nil && info.Size() > 0
}

// scanOutput is one drained Scan stream: files in emission order (stream order
// is load-bearing — the serial record precedes its episodes), plus lookup
// indexes and the carried warnings.
type scanOutput struct {
	files    []*scannerv1.DiscoveredFile
	byRel    map[string]*scannerv1.DiscoveredFile
	index    map[string]int
	warnings []string
}

// drainScan runs one Scan over root and collects the stream in order.
func drainScan(t *testing.T, s *scannerImpl, root string) *scanOutput {
	t.Helper()
	ch, err := s.Scan(context.Background(), &scannerv1.ScanRequest{
		LibraryPath: root,
		ModuleType:  "serial",
		Options:     mustStruct(t, map[string]any{"structure": "series-directories"}),
	})
	if err != nil {
		t.Fatalf("Scan: %v", err)
	}
	out := &scanOutput{byRel: map[string]*scannerv1.DiscoveredFile{}, index: map[string]int{}}
	for f := range ch {
		out.index[f.GetRelativePath()] = len(out.files)
		out.files = append(out.files, f)
		out.byRel[f.GetRelativePath()] = f
		out.warnings = append(out.warnings, f.GetWarnings()...)
	}
	return out
}

// identified runs Identify over one discovered file exactly like the drain
// (internal/scan persist) and returns the parsed facts as a plain map.
func identified(t *testing.T, s *scannerImpl, f *scannerv1.DiscoveredFile) map[string]any {
	t.Helper()
	res, err := s.Identify(context.Background(), &scannerv1.IdentifyRequest{File: f, ModuleType: "serial"})
	if err != nil {
		t.Fatalf("Identify %q: %v", f.GetRelativePath(), err)
	}
	raw, err := res.GetParsed().MarshalJSON()
	if err != nil {
		t.Fatalf("marshal parsed for %q: %v", f.GetRelativePath(), err)
	}
	var m map[string]any
	if err := jsonUnmarshal(raw, &m); err != nil {
		t.Fatalf("unmarshal parsed for %q: %v", f.GetRelativePath(), err)
	}
	return m
}

// factList reads a parsed facts array (sidecars / series_sidecars) as maps.
func factList(t *testing.T, parsed map[string]any, key string) []map[string]any {
	t.Helper()
	raw, ok := parsed[key].([]any)
	if !ok {
		t.Fatalf("parsed[%q] missing or not a list: %v", key, parsed[key])
	}
	out := make([]map[string]any, 0, len(raw))
	for _, e := range raw {
		m, ok := e.(map[string]any)
		if !ok {
			t.Fatalf("parsed[%q] element not an object: %v", key, e)
		}
		out = append(out, m)
	}
	return out
}

// warningsMatching returns the warnings containing every needle.
func warningsMatching(warnings []string, needles ...string) []string {
	var out []string
	for _, w := range warnings {
		all := true
		for _, n := range needles {
			if !strings.Contains(w, n) {
				all = false
				break
			}
		}
		if all {
			out = append(out, w)
		}
	}
	return out
}

// assertSerialRecord checks the marker facts of a directory-backed serial
// record (design.md §Interfaces §1) via Identify.
func assertSerialRecord(t *testing.T, s *scannerImpl, out *scanOutput, rel, dirName string) map[string]any {
	t.Helper()
	f, ok := out.byRel[rel]
	if !ok {
		t.Fatalf("serial record %q not emitted; got %d files", rel, len(out.files))
	}
	if out.index[rel] != 0 && !recordAfterNothingOfItsOwn(t, out, rel) {
		t.Fatalf("record %q emitted at index %d, want before its episodes", rel, out.index[rel])
	}
	if len(f.GetFfprobeJson()) != 0 {
		t.Fatalf("directory-backed record %q carries %d ffprobe bytes, want empty", rel, len(f.GetFfprobeJson()))
	}
	parsed := identified(t, s, f)
	if parsed["serial_record"] != true {
		t.Fatalf("record %q serial_record = %v, want true", rel, parsed["serial_record"])
	}
	if parsed["dir_name_raw"] != dirName {
		t.Fatalf("record %q dir_name_raw = %v, want %q", rel, parsed["dir_name_raw"], dirName)
	}
	if parsed["backing"] != "directory" {
		t.Fatalf("record %q backing = %v, want directory", rel, parsed["backing"])
	}
	if parsed["series_relative_path"] != rel {
		t.Fatalf("record %q series_relative_path = %v, want %q", rel, parsed["series_relative_path"], rel)
	}
	factList(t, parsed, "series_sidecars") // present (possibly empty)
	return parsed
}

// recordAfterNothingOfItsOwn reports whether a record emitted after index 0 is
// still ahead of every file under its own directory (multi-serial streams).
func recordAfterNothingOfItsOwn(t *testing.T, out *scanOutput, rel string) bool {
	t.Helper()
	for other, idx := range out.index {
		if strings.HasPrefix(other, rel+"/") && idx < out.index[rel] {
			return false
		}
	}
	return true
}

// TestWalkSerialDirs — probe deb03f5f7a07b865 (box 2.1). Each depth-1
// subdirectory with a direct video yields ONE serial record (marker facts,
// empty ffprobe) emitted BEFORE its probed episodes; two same-show cours
// directories produce two distinct records.
func TestWalkSerialDirs(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root,
		"Bleach S01/Bleach S01E01.mkv",
		"Bleach S01/Bleach S01E02.mkv",
		"Cowboy Bebop/Cowboy Bebop E01.mp4",
	)
	s := &scannerImpl{}
	out := drainScan(t, s, root)

	if len(out.files) != 5 { // 2 records + 3 episodes
		t.Fatalf("emitted %d files, want 5: %v", len(out.files), relsOf(out))
	}
	assertSerialRecord(t, s, out, "Bleach S01", "Bleach S01")
	assertSerialRecord(t, s, out, "Cowboy Bebop", "Cowboy Bebop")

	// Stream order: each record precedes its own episodes.
	for _, tc := range []struct{ record, episode string }{
		{"Bleach S01", "Bleach S01/Bleach S01E01.mkv"},
		{"Bleach S01", "Bleach S01/Bleach S01E02.mkv"},
		{"Cowboy Bebop", "Cowboy Bebop/Cowboy Bebop E01.mp4"},
	} {
		if out.index[tc.record] >= out.index[tc.episode] {
			t.Fatalf("record %q (idx %d) not before episode %q (idx %d)",
				tc.record, out.index[tc.record], tc.episode, out.index[tc.episode])
		}
		// Episode stamping: series_relative_path is its own serial (§2).
		parsed := identified(t, s, out.byRel[tc.episode])
		if parsed["series_relative_path"] != tc.record {
			t.Fatalf("episode %q series_relative_path = %v, want %q", tc.episode, parsed["series_relative_path"], tc.record)
		}
		if sidecars := factList(t, parsed, "sidecars"); len(sidecars) != 0 {
			t.Fatalf("episode %q has sidecars %v, want none", tc.episode, sidecars)
		}
	}

	// Two distinct serial records — never merged (box 2.1 tail).
	records := 0
	for _, f := range out.files {
		if identified(t, s, f)["serial_record"] == true {
			records++
		}
	}
	if records != 2 {
		t.Fatalf("got %d serial records, want 2 (cours stay distinct)", records)
	}
}

// TestDeepVideoWarns — probe d16c371b67739c27 (box 2.2). A video nested deeper
// than a serial dir's direct children is not discovered and surfaces exactly
// one warning naming the serial and the unexpected file.
func TestDeepVideoWarns(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root,
		"Show/ep1.mkv",
		"Show/Extras/extra.mkv",
	)
	s := &scannerImpl{}
	out := drainScan(t, s, root)

	if _, leaked := out.byRel["Show/Extras/extra.mkv"]; leaked {
		t.Fatal("deep video Show/Extras/extra.mkv was discovered — must be excluded")
	}
	if _, ok := out.byRel["Show"]; !ok {
		t.Fatal("serial record Show not emitted")
	}
	if _, ok := out.byRel["Show/ep1.mkv"]; !ok {
		t.Fatal("direct episode Show/ep1.mkv not emitted")
	}
	hits := warningsMatching(out.warnings, "Show", "Show/Extras/extra.mkv")
	if len(hits) != 1 {
		t.Fatalf("got %d warnings naming serial+file, want 1: %v", len(hits), out.warnings)
	}
}

// TestCoursStaySeparate — probe 87d0bb0b4f91f1f1 (box 2.3). Identity is
// strictly (library_id, relative_path): neither cours directory's episodes
// attach to the other serial's record.
func TestCoursStaySeparate(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root,
		"Bleach - Cour 1/Bleach S01E01.mkv",
		"Bleach - Cour 1/Bleach S01E02.mkv",
		"Bleach - Cour 2/Bleach S01E03.mkv",
		"Bleach - Cour 2/Bleach S01E04.mkv",
	)
	s := &scannerImpl{}
	out := drainScan(t, s, root)

	if len(out.files) != 6 { // 2 records + 4 episodes
		t.Fatalf("emitted %d files, want 6: %v", len(out.files), relsOf(out))
	}
	for _, tc := range []struct {
		dir      string
		episodes []string
	}{
		{"Bleach - Cour 1", []string{"Bleach S01E01.mkv", "Bleach S01E02.mkv"}},
		{"Bleach - Cour 2", []string{"Bleach S01E03.mkv", "Bleach S01E04.mkv"}},
	} {
		parsed := assertSerialRecord(t, s, out, tc.dir, tc.dir)
		if extra := factList(t, parsed, "series_sidecars"); len(extra) != 0 {
			t.Fatalf("record %q carries series_sidecars %v, want none", tc.dir, extra)
		}
		for _, ep := range tc.episodes {
			rel := tc.dir + "/" + ep
			got := identified(t, s, out.byRel[rel])["series_relative_path"]
			if got != tc.dir {
				t.Fatalf("episode %q attached to %v, want strictly its own dir %q", rel, got, tc.dir)
			}
		}
	}
	// The negative, explicitly: no emitted file carries the OTHER cours' path
	// as its series_relative_path.
	for _, f := range out.files {
		parsed := identified(t, s, f)
		got, _ := parsed["series_relative_path"].(string)
		own := strings.Contains(f.GetRelativePath(), "Cour 1")
		want := "Bleach - Cour 1"
		if !own {
			want = "Bleach - Cour 2"
		}
		if got != "" && got != want {
			t.Fatalf("file %q carries foreign series_relative_path %q (want %q)", f.GetRelativePath(), got, want)
		}
	}
}

// TestJunkExcluded — probe 729f1fe78b8f1286 (box 2.4). Files matching neither
// the video nor the sidecar extension set (extensionless smbdelete junk,
// .txt/.nfo) are excluded with no warning and no record; the sidecar extension
// set joins the walk (srt files are classified, never items).
func TestJunkExcluded(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root,
		"smbdeleteaaa3f21",
		"Show/ep1.mkv",
		"Show/smbdeleteBBB91c2",
		"Show/notes.txt",
		"Show/Eng/ep1.srt",
	)
	s := &scannerImpl{}
	out := drainScan(t, s, root)

	for _, junk := range []string{"smbdeleteaaa3f21", "Show/smbdeleteBBB91c2", "Show/notes.txt", "Show/Eng/ep1.srt"} {
		if _, leaked := out.byRel[junk]; leaked {
			t.Fatalf("junk/non-item %q was discovered as a file", junk)
		}
	}
	if _, ok := out.byRel["Show"]; !ok {
		t.Fatal("serial record Show not emitted")
	}
	if _, ok := out.byRel["Show/ep1.mkv"]; !ok {
		t.Fatal("episode Show/ep1.mkv not emitted")
	}
	for _, junk := range []string{"smbdelete", "notes.txt", ".srt"} {
		if hits := warningsMatching(out.warnings, junk); len(hits) != 0 {
			t.Fatalf("junk %q surfaced a warning: %v", junk, hits)
		}
	}
	// The sidecar joined the walk as a FACT, not an item.
	parsed := identified(t, s, out.byRel["Show/ep1.mkv"])
	sidecars := factList(t, parsed, "sidecars")
	if len(sidecars) != 1 || sidecars[0]["relative_path"] != "Show/Eng/ep1.srt" {
		t.Fatalf("episode sidecars = %v, want the Eng srt classified in", sidecars)
	}
}

// TestSrtAssociation — probe 38d51abe09bfbf7d (box 2.5). SxxExx in the sidecar
// filename links it to the matching episode; language comes from the containing
// folder (case-insensitive) or a filename tag, else empty; basis sxxexx.
func TestSrtAssociation(t *testing.T) {
	t.Run("folder language", func(t *testing.T) {
		root := t.TempDir()
		writeTree(t, root,
			"Show/Show S01E01.mkv",
			"Show/Show S01E02.mkv",
			"Show/Eng/Show S01E01.srt",
			"Show/rus/Show S01E02.srt",
		)
		s := &scannerImpl{}
		out := drainScan(t, s, root)

		for _, tc := range []struct{ ep, srt, lang string }{
			{"Show/Show S01E01.mkv", "Show/Eng/Show S01E01.srt", "Eng"},
			{"Show/Show S01E02.mkv", "Show/rus/Show S01E02.srt", "rus"},
		} {
			if _, leaked := out.byRel[tc.srt]; leaked {
				t.Fatalf("sidecar %q was emitted as a file — sidecars are never items", tc.srt)
			}
			sidecars := factList(t, identified(t, s, out.byRel[tc.ep]), "sidecars")
			if len(sidecars) != 1 {
				t.Fatalf("episode %q sidecars = %v, want 1", tc.ep, sidecars)
			}
			sc := sidecars[0]
			if sc["relative_path"] != tc.srt || sc["kind"] != "subtitle" || sc["language"] != tc.lang || sc["match_basis"] != "sxxexx" {
				t.Fatalf("episode %q sidecar = %v, want {%s subtitle %s sxxexx}", tc.ep, sc, tc.srt, tc.lang)
			}
		}
		parsed := assertSerialRecord(t, s, out, "Show", "Show")
		if extra := factList(t, parsed, "series_sidecars"); len(extra) != 0 {
			t.Fatalf("record series_sidecars = %v, want none (both sidecars episode-linked)", extra)
		}
	})

	t.Run("filename tag language", func(t *testing.T) {
		root := t.TempDir()
		writeTree(t, root,
			"Show/Show S01E01.mkv",
			"Show/SUB/Show.S01E01.eng.srt",
		)
		s := &scannerImpl{}
		out := drainScan(t, s, root)

		sidecars := factList(t, identified(t, s, out.byRel["Show/Show S01E01.mkv"]), "sidecars")
		if len(sidecars) != 1 {
			t.Fatalf("sidecars = %v, want 1", sidecars)
		}
		sc := sidecars[0]
		// SUB is not a language; the filename tag wins. Folder would have won
		// had it been a language folder — folder-first is asserted above.
		if sc["language"] != "eng" || sc["match_basis"] != "sxxexx" {
			t.Fatalf("sidecar = %v, want language eng + basis sxxexx", sc)
		}
	})

	t.Run("no language anywhere", func(t *testing.T) {
		root := t.TempDir()
		writeTree(t, root,
			"Show/Show S01E01.mkv",
			"Show/Show S01E01.srt",
		)
		s := &scannerImpl{}
		out := drainScan(t, s, root)

		sidecars := factList(t, identified(t, s, out.byRel["Show/Show S01E01.mkv"]), "sidecars")
		if len(sidecars) != 1 || sidecars[0]["language"] != "" {
			t.Fatalf("sidecars = %v, want one with empty language", sidecars)
		}
	})
}

// TestBareNumberFallback — probe 2195ddd74fa953fd (box 2.6). An .ass with no
// SxxExx token, only a bare episode number ("Show - 01 (1080p) [C48E56C8]"),
// associates via the bare_number basis — the resolution and CRC numbers must
// not hijack the match.
func TestBareNumberFallback(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root,
		"Show/Show S01E01.mkv",
		"Show/Show S01E02.mkv",
		"Show/SUB/Show - 01 (1080p) [C48E56C8].ass",
		"Show/SUB/Show - 02 (1080p) [D59F67D9].ass",
	)
	s := &scannerImpl{}
	out := drainScan(t, s, root)

	for _, tc := range []struct{ ep, ass string }{
		{"Show/Show S01E01.mkv", "Show/SUB/Show - 01 (1080p) [C48E56C8].ass"},
		{"Show/Show S01E02.mkv", "Show/SUB/Show - 02 (1080p) [D59F67D9].ass"},
	} {
		if _, leaked := out.byRel[tc.ass]; leaked {
			t.Fatalf("sidecar %q was emitted as a file", tc.ass)
		}
		sidecars := factList(t, identified(t, s, out.byRel[tc.ep]), "sidecars")
		if len(sidecars) != 1 {
			t.Fatalf("episode %q sidecars = %v, want 1", tc.ep, sidecars)
		}
		sc := sidecars[0]
		// SUB is not a language folder and the filename carries no tag.
		if sc["relative_path"] != tc.ass || sc["kind"] != "subtitle" || sc["language"] != "" || sc["match_basis"] != "bare_number" {
			t.Fatalf("episode %q sidecar = %v, want {%s subtitle `` bare_number}", tc.ep, sc, tc.ass)
		}
	}
}

// TestBareNamedEpisodeSidecar — probe b5d78250688f037a (box 2.1). Episodes
// named without SxxExx — a pure-number [NN] bracket ("Show II/[01]
// Episode.mkv") or a "<N> серия" marker — are indexed by the same number the
// parser extracts (design.md D-4), so a numbered .srt still associates via the
// bare_number basis; SxxExx episodes associate exactly as before. The
// sidecar-FILENAME grammar is untouched: a sidecar whose only number is a [NN]
// bracket carries no bare number and stays serial-level.
func TestBareNamedEpisodeSidecar(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root,
		"Show II/[01] Episode.mkv",
		"Show II/Episode - 01.srt",
		"Azure Harbor/[01] Azure Harbor 01 серия.mkv",
		"Azure Harbor/[01] Azure Harbor 01 серия.srt",
		"Bleach/Bleach S01E01.mkv",
		"Bleach/Bleach S01E01.srt",
		"Bracket Only/[01] Episode.mkv",
		"Bracket Only/[01] Episode.srt",
	)
	s := &scannerImpl{}
	out := drainScan(t, s, root)

	for _, tc := range []struct{ dir, ep, srt, basis string }{
		{"Show II", "Show II/[01] Episode.mkv", "Show II/Episode - 01.srt", matchBareNumber},
		{"Azure Harbor", "Azure Harbor/[01] Azure Harbor 01 серия.mkv", "Azure Harbor/[01] Azure Harbor 01 серия.srt", matchBareNumber},
		{"Bleach", "Bleach/Bleach S01E01.mkv", "Bleach/Bleach S01E01.srt", matchSxxExx},
	} {
		if _, leaked := out.byRel[tc.srt]; leaked {
			t.Fatalf("sidecar %q was emitted as a file — sidecars are never items", tc.srt)
		}
		sidecars := factList(t, identified(t, s, out.byRel[tc.ep]), "sidecars")
		if len(sidecars) != 1 {
			t.Fatalf("episode %q sidecars = %v, want 1", tc.ep, sidecars)
		}
		sc := sidecars[0]
		// No language folders or filename tags anywhere in these fixtures.
		if sc["relative_path"] != tc.srt || sc["kind"] != "subtitle" || sc["language"] != "" || sc["match_basis"] != tc.basis {
			t.Fatalf("episode %q sidecar = %v, want {%s subtitle `` %s}", tc.ep, sc, tc.srt, tc.basis)
		}
	}

	// The episode side widened, the sidecar side did not (design.md D-4):
	// "[01] Episode.srt" has no bare number under the untouched sidecar
	// grammar, so it attaches to the series record, never episode-linked.
	parsed := assertSerialRecord(t, s, out, "Bracket Only", "Bracket Only")
	level := factList(t, parsed, "series_sidecars")
	if len(level) != 1 || level[0]["relative_path"] != "Bracket Only/[01] Episode.srt" || level[0]["match_basis"] != nil {
		t.Fatalf("series_sidecars = %v, want the bracket-numbered srt serial-level", level)
	}
}

// TestSerialLevelOST — probe e805b89e8eea4ac1 (box 2.7). Audio nested several
// levels deep that matches no episode attaches to the series record's
// series_sidecars — never dropped silently, never an item, never episode-linked.
func TestSerialLevelOST(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root,
		"Show/Show S01E01.mkv",
		"Show/OST/Disc 1/Show OST - Overture.flac",
		"Show/OST/Disc 1/Show OST - Ending.mp3",
	)
	s := &scannerImpl{}
	out := drainScan(t, s, root)

	for _, ost := range []string{"Show/OST/Disc 1/Show OST - Overture.flac", "Show/OST/Disc 1/Show OST - Ending.mp3"} {
		if _, leaked := out.byRel[ost]; leaked {
			t.Fatalf("serial-level sidecar %q was emitted as a file", ost)
		}
	}
	parsed := assertSerialRecord(t, s, out, "Show", "Show")
	level := factList(t, parsed, "series_sidecars")
	if len(level) != 2 {
		t.Fatalf("series_sidecars = %v, want the 2 OST tracks", level)
	}
	for i, want := range []string{"Show/OST/Disc 1/Show OST - Ending.mp3", "Show/OST/Disc 1/Show OST - Overture.flac"} {
		sc := level[i]
		if sc["relative_path"] != want || sc["kind"] != "audio" || sc["language"] != "" || sc["match_basis"] != nil {
			t.Fatalf("series_sidecars[%d] = %v, want {%s audio `` null}", i, sc, want)
		}
	}
	// Never episode-linked either.
	ep := identified(t, s, out.byRel["Show/Show S01E01.mkv"])
	if sidecars := factList(t, ep, "sidecars"); len(sidecars) != 0 {
		t.Fatalf("episode sidecars = %v, want none (OST is serial-level)", sidecars)
	}
}

// TestLooseTopLevelFile — probe cd6f6bbe663b2d1e (box 2.8). A video file
// directly in the library root becomes a file-backed serial record (backing
// "file", series_relative_path = the file's own path) plus that file as its
// single probed episode item.
func TestLooseTopLevelFile(t *testing.T) {
	root := t.TempDir()
	target := filepath.Join(root, "The_Ribbon_Hero_[ONA].mkv")
	writeTree(t, root, "The_Ribbon_Hero_[ONA].mkv", "smbdeleteCCC51f8")
	real := makeVideoOpt(t, target) // zero-byte fallback when ffmpeg is absent

	s := &scannerImpl{}
	out := drainScan(t, s, root)

	if _, leaked := out.byRel["smbdeleteCCC51f8"]; leaked {
		t.Fatal("root junk was discovered")
	}
	if len(out.files) != 2 {
		t.Fatalf("emitted %d files, want 2 (record + episode): %v", len(out.files), relsOf(out))
	}
	record := out.files[0]
	parsed := identified(t, s, record)
	if parsed["serial_record"] != true || parsed["backing"] != "file" {
		t.Fatalf("first file parsed = %v, want a file-backed serial record", parsed)
	}
	if parsed["series_relative_path"] != "The_Ribbon_Hero_[ONA].mkv" {
		t.Fatalf("series_relative_path = %v, want the file's own path", parsed["series_relative_path"])
	}
	episode := out.files[1]
	if episode.GetRelativePath() != "The_Ribbon_Hero_[ONA].mkv" {
		t.Fatalf("episode rel = %q, want the same file", episode.GetRelativePath())
	}
	if real {
		if len(record.GetFfprobeJson()) == 0 || len(episode.GetFfprobeJson()) == 0 {
			t.Fatal("file-backed serial with real media: record AND episode must carry probe JSON (Interfaces §4)")
		}
	} else {
		// Soft-fail like base-scanner: still emitted, warning carried, empty probe.
		if len(episode.GetFfprobeJson()) != 0 || len(episode.GetWarnings()) == 0 {
			t.Fatal("unprobeable episode must be emitted with empty probe + a warning (AC-6)")
		}
	}
}

// TestUnicodeSerialName — probe cbaf65a0065ee7b4 (scanner half). Cyrillic /
// mixed-script directory and file names flow through discovery, facts, and
// sidecar association verbatim.
func TestUnicodeSerialName(t *testing.T) {
	const dir = "Необычный адвокат У Ён У Extraordinary Attorney Woo.2022.S01"
	root := t.TempDir()
	writeTree(t, root,
		dir+"/Необычный адвокат У Ён У S01E01.mkv",
		dir+"/Eng/Необычный адвокат У Ён У S01E01.srt",
	)
	s := &scannerImpl{}
	out := drainScan(t, s, root)

	if len(out.files) != 2 {
		t.Fatalf("emitted %d files, want 2: %v", len(out.files), relsOf(out))
	}
	parsed := assertSerialRecord(t, s, out, dir, dir)
	if parsed["dir_name_raw"] != dir {
		t.Fatalf("dir_name_raw = %v, want the Cyrillic name verbatim", parsed["dir_name_raw"])
	}
	epRel := dir + "/Необычный адвокат У Ён У S01E01.mkv"
	srtRel := dir + "/Eng/Необычный адвокат У Ён У S01E01.srt"
	ep := identified(t, s, out.byRel[epRel])
	if ep["series_relative_path"] != dir {
		t.Fatalf("episode series_relative_path = %v, want %q", ep["series_relative_path"], dir)
	}
	sidecars := factList(t, ep, "sidecars")
	if len(sidecars) != 1 || sidecars[0]["relative_path"] != srtRel || sidecars[0]["language"] != "Eng" || sidecars[0]["match_basis"] != "sxxexx" {
		t.Fatalf("episode sidecars = %v, want the Cyrillic srt (Eng, sxxexx)", sidecars)
	}
}

// TestStructureKnob guards design.md §Interfaces §3: any `structure` option
// value other than "series-directories" — including an absent one — is a fatal
// config error; the accepted value opens the stream.
func TestStructureKnob(t *testing.T) {
	root := t.TempDir()
	writeTree(t, root, "Show/ep1.mkv")

	s := &scannerImpl{}
	for _, tc := range []struct {
		name    string
		options map[string]any
		wantErr bool
	}{
		{name: "absent", options: nil, wantErr: true},
		{name: "other value", options: map[string]any{"structure": "flat"}, wantErr: true},
		{name: "accepted", options: map[string]any{"structure": "series-directories"}, wantErr: false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			req := &scannerv1.ScanRequest{LibraryPath: root, ModuleType: "serial"}
			if tc.options != nil {
				req.Options = mustStruct(t, tc.options)
			}
			ch, err := s.Scan(context.Background(), req)
			if tc.wantErr {
				if err == nil {
					for range ch {
					}
					t.Fatal("Scan accepted a disallowed structure option")
				}
				return
			}
			if err != nil {
				t.Fatalf("Scan rejected the accepted option: %v", err)
			}
			n := 0
			for range ch {
				n++
			}
			if n != 2 {
				t.Fatalf("emitted %d files, want 2", n)
			}
		})
	}
}

// relsOf lists the emitted relative paths (failure diagnostics).
func relsOf(out *scanOutput) []string {
	rels := make([]string, 0, len(out.files))
	for _, f := range out.files {
		rels = append(rels, f.GetRelativePath())
	}
	return rels
}
